const REASON = 'Buffer: this app always feeds the N3 lexer a string, so the'
  + ' buffer polyfill is not in the browser bundle (tools/shim-node-buffer.mjs).'
  + ' Whoever lands here is giving N3 byte chunks — add the polyfill back then.';

// `isBuffer` answers false instead of throwing: that is a QUESTION, not a use,
// and the answer is false here by construction. The rest throws.
function fail() { throw new Error(REASON); }

export const Buffer = {
  isBuffer: () => false,
  concat: fail,
  from: fail,
  alloc: fail,
  allocUnsafe: fail,
  byteLength: fail,
};

export const kMaxLength = 0;
export const INSPECT_MAX_BYTES = 50;

export default { Buffer, kMaxLength, INSPECT_MAX_BYTES };
