
/**
 *  @typedef {object} ArtifactBlock
 *  @property {string[]} classes
 *  @property {string|null} bundleClass
 *  @property {string|null} conformsOperator
 *  @property {string|null} entrypoint
 *  @property {string|null} sha256
 *  @property {string|null} bundles
 *  @typedef {object} EditingBlock
 *  @property {string|null} defaultProfile
 *  @property {string[]} operators
 *  @property {string[]} leftOperands
 *  @property {string[]} partyRegisterBases
 *  @typedef {object} Profile
 *  @property {string|null} name
 *  @property {string[]} vocabulary
 *  @property {string[]} examples
 *  @property {Record<string,string>} prefixes
 *  @property {ArtifactBlock|null} artifacts
 *  @property {EditingBlock} editing
 *  @property {string|null} language
 *  @property {string[]} formShapes
 *  @property {string[]} shapeTexts
 *  @property {string[]} constraintProperties
 */
/** @type {Profile} */
export const GENERIC_PROFILE = Object.freeze({
  name: null,
  vocabulary: Object.freeze([]),
  examples: Object.freeze([]),
  prefixes: Object.freeze({}),
  artifacts: null,
  editing: Object.freeze({
    defaultProfile: null,
    operators: Object.freeze([]),
    leftOperands: Object.freeze([]),
    partyRegisterBases: Object.freeze([]),
  }),
  language: null,
  formShapes: Object.freeze([]),
  shapeTexts: Object.freeze([]),
  constraintProperties: Object.freeze([]),
});
/** @type {Profile} */
// The worker gets the bundle PER MESSAGE: a module global does not cross the
// worker boundary, unlike the static prefix and label tables beside it.
let active = GENERIC_PROFILE;

function stringList(v) {
  if (!Array.isArray(v)) return [];
  return v.filter((x) => typeof x === 'string' && x).map((x) => String(x));
}

function stringOrNull(v) {
  return typeof v === 'string' && v ? v : null;
}
function stringTable(v) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return {};
  const out = {};
  for (const [k, w] of Object.entries(v)) {
    if (typeof k === 'string' && k && typeof w === 'string' && w) out[k] = w;
  }
  return out;
}
function normalizeArtifacts(v) {
  if (!v || typeof v !== 'object' || Array.isArray(v)) return null;
  const classes = stringList(v.classes);
  const bundleClass = stringOrNull(v.bundleClass);
  const conformsOperator = stringOrNull(v.conformsOperator);
  const entrypoint = stringOrNull(v.entrypoint);
  const sha256 = stringOrNull(v.sha256);
  const bundles = stringOrNull(v.bundles);
  if (!classes.length && !bundleClass && !conformsOperator
    && !entrypoint && !sha256 && !bundles) return null;
  return { classes, bundleClass, conformsOperator, entrypoint, sha256, bundles };
}
function normalizeEditing(v) {
  const b = (v && typeof v === 'object' && !Array.isArray(v)) ? v : {};
  return {
    defaultProfile: stringOrNull(b.defaultProfile),
    operators: stringList(b.operators),
    leftOperands: stringList(b.leftOperands),
    partyRegisterBases: stringList(b.partyRegisterBases),
  };
}
/** @param {unknown} raw @returns {Profile} */
export function normalizeProfile(raw) {
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) return GENERIC_PROFILE;
  return {
    name: stringOrNull(raw.name),
    vocabulary: stringList(raw.vocabulary),
    examples: stringList(raw.examples),
    prefixes: stringTable(raw.prefixes),
    artifacts: normalizeArtifacts(raw.artifacts),
    editing: normalizeEditing(raw.editing),
    language: stringOrNull(raw.language),
    formShapes: stringList(raw.formShapes),
    shapeTexts: stringList(raw.shapeTexts),
    constraintProperties: stringList(raw.constraintProperties),
  };
}
/** @param {unknown} raw @returns {Profile} */
export function setProfile(raw) {
  active = raw ? normalizeProfile(raw) : GENERIC_PROFILE;
  return active;
}
/** @returns {Profile} */
export function profile() {
  return active;
}
export function profileName() {
  return active.name;
}
export function profileVocabulary() {
  return active.vocabulary;
}
export function profileExamples() {
  return active.examples;
}
export function profilePrefixes() {
  return active.prefixes;
}
export function artifactProfile() {
  return active.artifacts;
}
export function editProfile() {
  return active.editing;
}
export function profileLang() {
  return active.language;
}
export function profileShapeTexts() {
  return active.shapeTexts;
}
export function profileConstraintProperties() {
  return active.constraintProperties;
}

export async function fetchProfile(base = 'data/', fetchImpl = undefined) {
  const doFetch = fetchImpl || (typeof fetch === 'function' ? fetch : null);
  const errors = [];
  if (!doFetch) return { profile: GENERIC_PROFILE, errors };
  const url = base + 'profile.json';
  let raw = null;
  try {
    const res = await doFetch(url);
    if (!res || !res.ok) return { profile: GENERIC_PROFILE, errors };
    raw = await res.json();
  } catch (err) {

    errors.push({ url, message: (err && err.message) || String(err) });
    return { profile: GENERIC_PROFILE, errors };
  }
  const p = normalizeProfile(raw);
  const texts = [];
  for (const path of p.formShapes) {
    const shapeUrl = base + path;
    try {
      const res = await doFetch(shapeUrl);
      if (!res || !res.ok) {
        errors.push({ url: shapeUrl, message: `HTTP ${(res && res.status) || '?'}` });
        continue;
      }
      texts.push(await res.text());
    } catch (err) {
      errors.push({ url: shapeUrl, message: (err && err.message) || String(err) });
    }
  }
  return { profile: { ...p, shapeTexts: texts }, errors };
}