const REASON = 'node stream layer: this app does not use it, so it is not in'
  + ' the browser bundle (tools/shim-node-stream.mjs). Whoever lands here uses'
  + ' store.match(), store.removeMatches() of de N3 StreamParser/StreamWriter —'
  + ' replace that with getQuads/removeQuad, or remove the shim.';

// n3's node-stream layer, replaced by an empty shim in the BROWSER bundle only:
// 113,321 bytes out of the entry chunk and 113,247 out of the worker chunk, and
// not one line of it ever runs. Rollup cannot tree-shake it: `class
// DatasetCoreAndReadableStream extends Readable` uses `Readable` in a CLASS
// HEADER, which executes at module load.
//
// Safe because all four uses are dead here: store.match() (zero calls in src/),
// store.removeMatches() (only ever in lists of method names), StreamParser and
// StreamWriter (zero references), and Buffer.concat in N3Lexer (the app always
// feeds the lexer a STRING).
//
// FAIL LOUDLY: these throw on CONSTRUCTION rather than being working mini
// implementations, so a new use falls over in the gate instead of in production.
// tools/shim-node-stream.test.mjs re-checks these assumptions against the
// INSTALLED n3 and against src/.
class Huls {
  constructor() { throw new Error(REASON); }
}

export class Readable extends Huls {}
export class Writable extends Huls {}
export class Duplex extends Huls {}
export class Transform extends Huls {}
export class PassThrough extends Huls {}
export class Stream extends Huls {}

export const pipeline = () => { throw new Error(REASON); };
export const finished = () => { throw new Error(REASON); };

export default { Readable, Writable, Duplex, Transform, PassThrough, Stream, pipeline, finished };
