import {
  loadSources, scopeNavToSet, knownSourcePrefixes, registerPrefixes, registerLabelKeys,
} from './parse.js';
import { setLang } from './i18n.js';
import { serializeStore } from './graph-transfer.js';
import { setProfile } from './profile.js';
import { defaultRegisterPrefixes } from './register-prefixes.js';
import { DEFAULT_PROPERTY_LABEL_KEYS } from './register-labels.js';

registerLabelKeys(DEFAULT_PROPERTY_LABEL_KEYS);

self.onmessage = (e) => {
  const { sources, setScope, lang, profile } = e.data || {};
  try {
    setProfile(profile);
    registerPrefixes(defaultRegisterPrefixes());
    setLang(lang);
    const result = loadSources(sources || [], (p) => self.postMessage({ type: 'progress', ...p }));
    const scoped = setScope ? scopeNavToSet(result.nav, result.store, setScope) : null;
    self.postMessage({
      type: 'model',
      model: result.model,
      nav: result.nav,
      scopedNav: scoped ? scoped.nav : null,
      errors: result.errors,
      quadCount: result.quadCount,
      timings: result.timings,
      prefixes: knownSourcePrefixes(),
    });
    const { termText, termOffsets, quadTable } = serializeStore(result.store);
    self.postMessage({ type: 'store', termText, termOffsets, quadTable },
      [quadTable.buffer, termOffsets.buffer]);
  } catch (err) {
    self.postMessage({ type: 'error', message: (err && err.message) || String(err) });
  }
};
