import * as N3 from 'n3';

const { Store, termFromId } = N3;

export function createStore() { return new Store(); }

// N3 numbers terms on first mention and iterates its indexes ASCENDING, so the
// number assignment fixes the iteration order of the whole store. Handing the
// numbers out again on the receiving side reordered 2,664 of 5,394 quads, which
// silently reorders every reference list the reader sees.
export function serializeStore(store) {
  const quads = store.getQuads(null, null, null, null);
  const termIds = [];
  const index = new Map();
  const add = (id) => {
    if (!index.has(id)) { index.set(id, termIds.length); termIds.push(id); }
  };
  const entities = store._entityIndex && store._entityIndex._entities;
  if (entities) {
    const used = new Set();
    for (const q of quads) {
      used.add(q.subject.id); used.add(q.predicate.id);
      used.add(q.object.id); used.add(q.graph.id);
    }
    for (const nr of Object.keys(entities).map(Number).sort((a, b) => a - b)) {
      if (used.has(entities[nr])) add(entities[nr]);
    }
  }
  const quadTable = new Uint32Array(quads.length * 4);
  let j = 0;
  for (const q of quads) {
    add(q.subject.id); add(q.predicate.id);
    add(q.object.id); add(q.graph.id);
    quadTable[j++] = index.get(q.subject.id);
    quadTable[j++] = index.get(q.predicate.id);
    quadTable[j++] = index.get(q.object.id);
    quadTable[j++] = index.get(q.graph.id);
  }
  const termOffsets = new Uint32Array(termIds.length + 1);
  for (let i = 0; i < termIds.length; i++) {
    termOffsets[i + 1] = termOffsets[i] + termIds[i].length;
  }
  const termText = termIds.join('');
  return { termText, termOffsets, quadTable };
}

export function hydrateInto(store, { termText, termOffsets, quadTable }, { chunkSize = 25000, onProgress = null } = {}) {
  const termCount = termOffsets.length - 1;
  const terms = new Array(termCount);
  for (let ix = 0; ix < termCount; ix++) {
    terms[ix] = termFromId(termText.substring(termOffsets[ix], termOffsets[ix + 1]));
  }
  const entityIndex = store._entityIndex;
  if (entityIndex && entityIndex._termToNewNumericId) {
    for (const t of terms) entityIndex._termToNewNumericId(t);
  }
  const term = (ix) => terms[ix];
  const totalQuads = quadTable.length / 4;
  return new Promise((resolve) => {
    let i = 0;
    const step = () => {
      const end = Math.min(totalQuads, i + chunkSize);
      for (; i < end; i++) {
        store.addQuad(term(quadTable[i * 4]), term(quadTable[i * 4 + 1]),
          term(quadTable[i * 4 + 2]), term(quadTable[i * 4 + 3]));
      }
      if (onProgress) onProgress(i, totalQuads);
      if (i < totalQuads) setTimeout(step, 0);
      else resolve(store);
    };
    step();
  });
}
