
import { profileLang } from './profile.js';

const BUILTIN_LANG_PREFERENCE = ['nl', 'en'];

const CHROME_LANGS = ['nl', 'en'];

function readLangPreference() {
  let raw = null;
  try { raw = import.meta.env && import.meta.env.VITE_LANG_PREFERENCE; } catch { raw = null; }
  const list = String(raw || '').split(',')
    .map((s) => s.trim().toLowerCase()).filter(Boolean);
  const unique = [...new Set(list)];
  return unique.length ? unique : BUILTIN_LANG_PREFERENCE;
}

export const LANG_PREFERENCE = readLangPreference();

const SELECTABLE = LANG_PREFERENCE.filter((l) => CHROME_LANGS.includes(l));
export const LANGS = SELECTABLE.length ? SELECTABLE : CHROME_LANGS;

const CORE_DEFAULT = LANGS.includes('en') ? 'en' : LANGS[0];

export function defaultLang() {
  const fromBundle = profileLang();
  const s = String(fromBundle || '').toLowerCase().split('-')[0];
  return LANGS.includes(s) ? s : CORE_DEFAULT;
}

const LANG_NAMES = { nl: 'Nederlands', en: 'English' };

export function langName(l) {
  const code = String(l || '').toLowerCase();
  if (LANG_NAMES[code]) return LANG_NAMES[code];
  try {
    const n = new Intl.DisplayNames([code], { type: 'language' }).of(code);
    if (n && n.toLowerCase() !== code) return n;
  } catch {  }
  return code.toUpperCase();
}

const NUM_LOCALE = { nl: 'nl-NL', en: 'en-GB' };

let current = null;

export function normalizeLang(l) {
  const s = String(l || '').toLowerCase().split('-')[0];
  return LANGS.includes(s) ? s : defaultLang();
}

export function setLang(l) {
  current = normalizeLang(l);
  chainOfCurrent = null;
  return current;
}

export function getLang() { return current || defaultLang(); }

export function num(n, lang = undefined) {
  const l = lang || getLang();
  if (typeof n !== 'number' || !Number.isFinite(n)) return String(n);
  return n.toLocaleString(NUM_LOCALE[l] || NUM_LOCALE[defaultLang()] || 'en-GB');
}

export function collate(a, b, lang = getLang()) {
  return String(a || '').localeCompare(String(b || ''), lang);
}

const CHAIN_CACHE = new Map();
let chainOfCurrent = null;

export function langChain(lang = getLang()) {
  const active = getLang();
  if (lang === active && chainOfCurrent) return chainOfCurrent;
  const known = CHAIN_CACHE.get(lang);
  if (known) return known;
  const l = normalizeLang(lang);
  const chain = CHAIN_CACHE.get(l) || [l, ...LANG_PREFERENCE.filter((x) => x !== l)];
  CHAIN_CACHE.set(l, chain);
  if (CHAIN_CACHE.size < 64) CHAIN_CACHE.set(lang, chain);
  if (lang === active) chainOfCurrent = chain;
  return chain;
}

function rankIn(chain, tag) {
  const t = tag;
  for (let i = 0; i < chain.length; i++) {
    if (t === chain[i]) return i * 2;
    if (t.startsWith(chain[i] + '-')) return i * 2 + 1;
  }
  const untagged = chain.length * 2;
  return t === '' ? untagged : untagged + 1;
}

export function langRank(tag, lang = getLang()) {
  return rankIn(langChain(lang), String(tag || '').toLowerCase());
}

// Fallback chain: preference list in order -> untagged -> remaining languages,
// the last sorted so the parse order cannot decide what the reader sees.
export function pickLabel(terms, lang = getLang()) {
  const chain = langChain(lang);
  const restRank = chain.length * 2 + 1;
  let best = null;
  let bestRank = Infinity;
  let bestTag = '';
  for (const t of terms || []) {
    if (!t || (t.termType && t.termType !== 'Literal')) continue;
    if (typeof t.value !== 'string') continue;
    const tag = String(t.language || '').toLowerCase();
    const r = rankIn(chain, tag);
    const wins = r < bestRank || (r === bestRank && r === restRank && tag < bestTag);
    if (wins) { bestRank = r; best = t; bestTag = tag; }
    if (r === 0) break;
  }
  return best ? best.value : null;
}

export function pickFromTable(table, lang = getLang()) {
  if (!table) return '';
  const chain = langChain(lang);
  for (const l of chain) if (table[l]) return table[l];
  for (const l of Object.keys(table).sort()) if (table[l]) return table[l];
  return '';
}

